import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"51、【震】 震下震上","description":"橫渠易說 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"橫渠易說 - 51、【震】 震下震上"},"headers":[],"relativePath":"classics/hengqu/053.md","filePath":"classics/hengqu/053.md"}'),l={name:"classics/hengqu/053.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><h3 id="彖曰-震亨-震來虩虩-恐致福也-笑言啞啞-後有則也。-震驚百里-驚遠而懼邇也-出可以守宗廟社稷以為祭主也。" tabindex="-1">彖曰：“震亨，震來虩虩”，恐致福也；“笑言啞啞”，後有則也。“震驚百里”，驚遠而懼邇也，出可以守宗廟社稷以為祭主也。 <a class="header-anchor" href="#彖曰-震亨-震來虩虩-恐致福也-笑言啞啞-後有則也。-震驚百里-驚遠而懼邇也-出可以守宗廟社稷以為祭主也。" aria-label="Permalink to “彖曰：“震亨，震來虩虩”，恐致福也；“笑言啞啞”，後有則也。“震驚百里”，驚遠而懼邇也，出可以守宗廟社稷以為祭主也。”">​</a></h3><h3 id="象曰-洊雷震-君子以恐懼修省。" tabindex="-1">象曰：洊雷震，君子以恐懼修省。 <a class="header-anchor" href="#象曰-洊雷震-君子以恐懼修省。" aria-label="Permalink to “象曰：洊雷震，君子以恐懼修省。”">​</a></h3><p>此卦純以君出子在而言，則震之體全而用顯，故曰“出可以守宗廟社稷”，不雜言君父共國之時也。</p><h3 id="初九-震來虩虩-後笑言啞啞-吉。-象曰-震來虩虩-恐致福也-笑言啞啞-後有則也。" tabindex="-1">初九，震來虩虩，後笑言啞啞，吉。 象曰：“震來虩虩”，恐致福也；“笑言啞啞”，後有則也。 <a class="header-anchor" href="#初九-震來虩虩-後笑言啞啞-吉。-象曰-震來虩虩-恐致福也-笑言啞啞-後有則也。" aria-label="Permalink to “初九，震來虩虩，後笑言啞啞，吉。 象曰：“震來虩虩”，恐致福也；“笑言啞啞”，後有則也。”">​</a></h3><h3 id="六二-震來厲-億喪貝-躋於九陵-勿逐-七日得。-象曰-震來厲-乘剛也。" tabindex="-1">六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。 象曰：“震來厲”，乘剛也。 <a class="header-anchor" href="#六二-震來厲-億喪貝-躋於九陵-勿逐-七日得。-象曰-震來厲-乘剛也。" aria-label="Permalink to “六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。 象曰：“震來厲”，乘剛也。”">​</a></h3><p>初動而之上，故曰“躋於九陵”。億，必也。</p><h3 id="六三-震蘇蘇-震行無眚。-象曰-震蘇蘇-位不當也。" tabindex="-1">六三，震蘇蘇，震行無眚。 象曰：“震蘇蘇”，位不當也。 <a class="header-anchor" href="#六三-震蘇蘇-震行無眚。-象曰-震蘇蘇-位不當也。" aria-label="Permalink to “六三，震蘇蘇，震行無眚。 象曰：“震蘇蘇”，位不當也。”">​</a></h3><p>蘇蘇亦索索之義，處非其地，故危困不一，能懼而改行，則無眚矣。</p><h3 id="九四-震遂泥。-象曰-震遂泥-未光也。" tabindex="-1">九四，震遂泥。 象曰：“震遂泥”，未光也。 <a class="header-anchor" href="#九四-震遂泥。-象曰-震遂泥-未光也。" aria-label="Permalink to “九四，震遂泥。 象曰：“震遂泥”，未光也。”">​</a></h3><p>處眾陰之中，為眾附比，剛陽之德而以位陰，故泥而未光也。</p><h3 id="六五-震往來厲-億無喪有事。-象曰-震往來厲-危行也-其事在中-大無喪也。" tabindex="-1">六五，震往來厲，億無喪有事。 象曰：“震往來厲”，危行也，其事在中，大無喪也。 <a class="header-anchor" href="#六五-震往來厲-億無喪有事。-象曰-震往來厲-危行也-其事在中-大無喪也。" aria-label="Permalink to “六五，震往來厲，億無喪有事。 象曰：“震往來厲”，危行也，其事在中，大無喪也。”">​</a></h3><p>懼往亦厲，懼來亦厲，能行己以危，則富貴可保，故曰“無喪有事”，猶雲不失其所有也。以其乘剛故危，以其在中故無喪，禍至與不至皆懼，則無喪有事。一有云懼陰之中。</p><h3 id="上六-震索索-視矍矍-徵兇。震不於其躬-於其鄰-無咎。婚媾有言。-象曰-震索索-中未得也。雖兇無咎-畏鄰戒也。" tabindex="-1">上六，震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。 象曰：“震索索”，中未得也。雖兇無咎，畏鄰戒也。 <a class="header-anchor" href="#上六-震索索-視矍矍-徵兇。震不於其躬-於其鄰-無咎。婚媾有言。-象曰-震索索-中未得也。雖兇無咎-畏鄰戒也。" aria-label="Permalink to “上六，震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。 象曰：“震索索”，中未得也。雖兇無咎，畏鄰戒也。”">​</a></h3><p>危以動，懼以語，無交而求，則民弗與也，故以徵則兇，能以鄰為懼，則可免咎。鄰謂五也，五既附四，己或與焉，則招悔而有言矣，能以鄰為戒，不待及身而戒則無咎。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
